    seq = None
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0:
                continue
            # Horizontal-color key: identical row runs across multiple rows.
            colors = []
            cc = c
            while cc < w and g[r][cc] != 0:
                colors.append(g[r][cc]); cc += 1
            if len(colors) >= 2:
                rr = r
                while rr < h and g[rr][c:cc] == colors:
                    rr += 1
                if rr-r >= 2:
                    seq = colors
                    break
        if seq:
            break
    if seq is None:
        for c in range(w):
            for r in range(h):
                if g[r][c] == 0:
                    continue
                colors=[]; rr=r
                while rr<h and g[rr][c]!=0:
                    colors.append(g[rr][c]); rr+=1
                if len(colors)>=2:
                    cc=c
                    while cc<w and [g[x][cc] for x in range(r,rr)]==colors:
                        cc+=1
                    if cc-c>=2:
                        seq=colors
                        break
            if seq:
                break
    if not seq or 1 not in seq:
        return g
    # Extract the color-1 motif's bounding box.
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    if not pts:
        return g
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    motif=[[1 if g[r][c]==1 else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    # Remove only motif cells, then place one copy per palette color, with
    # the original color-1 copy retaining its location in the sequence.
    for r,c in pts: g[r][c]=0
    start=r0-seq.index(1)*(r1-r0+1)
    for k,color in enumerate(seq):
        for dr,row in enumerate(motif):
            for dc,v in enumerate(row):
                if v and 0<=start+k*len(motif)+dr<h and 0<=c0+dc<w:
                    g[start+k*len(motif)+dr][c0+dc]=color
    return g

